def field_parts_with_seps(line: str, delim: Optional[str]) -> Tuple[List[str], List[str]]:
    """Return fields and the separator text immediately following each field."""
    fields=[]; seps=[]
    if delim is None:
        ms=list(re.finditer(r'\S+', line))
        for i,m in enumerate(ms):
            fields.append(m.group(0))
            end=m.end(); nxt=ms[i+1].start() if i+1 < len(ms) else end
            seps.append(line[end:nxt])
        return fields,seps
    try:
        parts=[]; last=0; sep_text=[]
        for m in re.finditer(delim, line):
            parts.append(line[last:m.start()]); sep_text.append(line[m.start():m.end()]); last=m.end()
        parts.append(line[last:]); sep_text.append('')
        return parts, sep_text
    except re.error:
        # literal fallback
        d=delim; start=0
        while True:
            j=line.find(d,start)
            if j<0: break
            fields.append(line[start:j]); seps.append(d); start=j+len(d)
        fields.append(line[start:]); seps.append('')
        return fields,seps

def expand_expr_indices(expr: str, L: int) -> List[int]:
    inds=[]
    for part in expr.split(','):
        part=part.strip()
        if not part: continue
        if '..' in part:
            a,b=part.split('..',1)
            start=0 if a=='' else idx_to_pos(int(a),L)
            end=L-1 if b=='' else idx_to_pos(int(b),L)
            if start is None or end is None: continue
            if start<=end: inds.extend(range(start,end+1))
            else: inds.extend(range(start,end-1,-1))
        else:
            try: p=idx_to_pos(int(part),L)
            except: p=None
            if p is not None: inds.append(p)
    return inds

def select_fields_accept(line: str, expr: str, delim: Optional[str]) -> str:
    fields,seps=field_parts_with_seps(line,delim)
    inds=expand_expr_indices(expr,len(fields))
    out=[]
    for pos,idx in enumerate(inds):
        if 0 <= idx < len(fields):
            out.append(fields[idx])
            if pos != len(inds)-1:
                out.append(seps[idx])
    return ''.join(out)
'''
